{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

type flagOptions struct {
	ungron    bool
	values    bool
	colorize  bool
	monochrome bool
	stream    bool
	insecure  bool
	json      bool
	noSort    bool
	version   bool
}

type pathComponent struct {
	isIndex bool
	index   int
	key     string
}

type statement struct {
	path  []pathComponent
	value interface{}
}

func main() {
	var opts flagOptions
	var args []string

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if strings.HasPrefix(arg, "-") {
			switch arg {
			case "-u", "--ungron":
				opts.ungron = true
			case "-v", "--values":
				opts.values = true
			case "-c", "--colorize":
				opts.colorize = true
			case "-m", "--monochrome":
				opts.monochrome = true
			case "-s", "--stream":
				opts.stream = true
			case "-k", "--insecure":
				opts.insecure = true
			case "-j", "--json":
				opts.json = true
			case "--no-sort":
				opts.noSort = true
			case "--version":
				opts.version = true
			case "-h", "--help":
				printHelp()
				return
			default:
				// ignore unknown flags
			}
		} else {
			args = append(args, arg)
		}
	}

	if opts.version {
		fmt.Println("gron version dev")
		return
	}

	var input io.Reader
	if len(args) == 0 || args[0] == "-" {
		input = os.Stdin
	} else {
		arg := args[0]
		if strings.HasPrefix(arg, "http://") || strings.HasPrefix(arg, "https://") {
			resp, err := http.Get(arg)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err)
				os.Exit(4)
			}
			defer resp.Body.Close()
			input = resp.Body
		} else {
			f, err := os.Open(arg)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err)
				os.Exit(1)
			}
			defer f.Close()
			input = f
		}
	}

	if opts.ungron {
		doUngron(input, opts)
	} else if opts.values {
		doValues(input, opts)
	} else {
		if opts.stream {
			doStreamGron(input, opts)
		} else {
			var val interface{}
			dec := json.NewDecoder(input)
			dec.UseNumber()
			if err := dec.Decode(&val); err != nil {
				fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err)
				os.Exit(3)
			}

			statements := make([]statement, 0)
			walk(val, []pathComponent{{key: "json"}}, &statements)

			if !opts.noSort {
				sort.Slice(statements, func(i, j int) bool {
					return naturalLess(formatPath(statements[i].path), formatPath(statements[j].path))
				})
			}

			for _, s := range statements {
				if opts.json {
					fmt.Println(formatJSON(s))
				} else {
					fmt.Println(formatStatement(s, opts.colorize))
				}
			}
		}
	}
}

func walk(val interface{}, path []pathComponent, statements *[]statement) {
	switch v := val.(type) {
	case map[string]interface{}:
		*statements = append(*statements, statement{path, v})
		// Sort keys to ensure deterministic order during traversal (though we sort at the end too)
		keys := make([]string, 0, len(v))
		for k := range v {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{key: k})
			walk(v[k], newPath, statements)
		}
	case []interface{}:
		*statements = append(*statements, statement{path, v})
		for i, item := range v {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{isIndex: true, index: i})
			walk(item, newPath, statements)
		}
	default:
		*statements = append(*statements, statement{path, v})
	}
}

func formatPath(path []pathComponent) string {
	var sb strings.Builder
	for i, comp := range path {
		if i == 0 {
			sb.WriteString(comp.key)
		} else if comp.isIndex {
			sb.WriteString("[" + strconv.Itoa(comp.index) + "]")
		} else {
			sb.WriteString(formatKey(comp.key))
		}
	}
	return sb.String()
}

func formatKey(key string) string {
	if isIdentifier(key) {
		return "." + key
	}
	return "[" + quoteString(key) + "]"
}

func isIdentifier(s string) bool {
	if s == "" || reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !unicode.IsLetter(r) && r != '$' && r != '_' {
				return false
			}
		} else {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '$' && r != '_' {
				return false
			}
		}
	}
	return true
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "false": true, "finally": true,
	"for": true, "function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true, "super": true,
	"switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
	"yield": true,
}

func quoteString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

func formatValue(val interface{}) string {
	switch v := val.(type) {
	case map[string]interface{}:
		return "{}"
	case []interface{}:
		return "[]"
	case json.Number:
		return v.String()
	case string:
		return quoteString(v)
	default:
		return fmt.Sprintf("%v", v)
	}
}

func formatStatement(s statement, colorize bool) string {
	pathStr := formatPath(s.path)
	valueStr := formatValue(s.value)
	if colorize {
		// TODO: Implement colorization
	}
	return pathStr + " = " + valueStr + ";"
}

func formatJSON(s statement) string {
	// Path as array of components
	pathArray := make([]interface{}, 0, len(s.path)-1)
	for i := 1; i < len(s.path); i++ {
		if s.path[i].isIndex {
			pathArray = append(pathArray, s.path[i].index)
		} else {
			pathArray = append(pathArray, s.path[i].key)
		}
	}

	val := s.value
	if _, ok := val.(map[string]interface{}); ok {
		val = map[string]interface{}{}
	} else if _, ok := val.([]interface{}); ok {
		val = []interface{}{}
	}

	res, _ := json.Marshal([]interface{}{pathArray, val})
	return string(res)
}

func naturalLess(s1, s2 string) bool {
	// A simple natural sort implementation
	i, j := 0, 0
	for i < len(s1) && j < len(s2) {
		r1 := rune(s1[i])
		r2 := rune(s2[j])
		if unicode.IsDigit(r1) && unicode.IsDigit(r2) {
			// Find full number
			k1 := i
			for k1 < len(s1) && unicode.IsDigit(rune(s1[k1])) {
				k1++
			}
			num1, _ := strconv.Atoi(s1[i:k1])

			k2 := j
			for k2 < len(s2) && unicode.IsDigit(rune(s2[k2])) {
				k2++
			}
			num2, _ := strconv.Atoi(s2[j:k2])

			if num1 != num2 {
				return num1 < num2
			}
			i, j = k1, k2
		} else {
			if r1 != r2 {
				return r1 < r2
			}
			i++
			j++
		}
	}
	return len(s1) < len(s2)
}

func doStreamGron(input io.Reader, opts flagOptions) {
	scanner := bufio.NewScanner(input)
	i := 0
	for scanner.Scan() {
		var val interface{}
		err := json.Unmarshal(scanner.Bytes(), &val)
		if err != nil {
			continue // Skip invalid lines or handle error
		}
		statements := make([]statement, 0)
		walk(val, []pathComponent{{key: "json"}, {isIndex: true, index: i}}, &statements)
		// ... sort and print ...
		// Actually, stream mode in gron collects ALL statements and then prints?
		// Let's check.
		i++
	}
}

// ... other functions ...
func printHelp() { /* ... */ }
func doUngron(input io.Reader, opts flagOptions) { /* ... */ }
func doValues(input io.Reader, opts flagOptions) { /* ... */ }
EOF
"}

