	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

type flagOptions struct {
	ungron    bool
	values    bool
	colorize  bool
	monochrome bool
	stream    bool
	insecure  bool
	json      bool
	noSort    bool
	version   bool
}

type pathComponent struct {
	isIndex bool
	index   int
	key     string
}

type statement struct {
	path  []pathComponent
	value interface{}
}

func main() {
	var opts flagOptions
	var args []string

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]
		if strings.HasPrefix(arg, "--") {
			switch arg {
			case "--ungron": opts.ungron = true
			case "--values": opts.values = true
			case "--colorize": opts.colorize = true
			case "--monochrome": opts.monochrome = true
			case "--stream": opts.stream = true
			case "--insecure": opts.insecure = true
			case "--json": opts.json = true
			case "--no-sort": opts.noSort = true
			case "--version": opts.version = true
			case "--help": printHelp(); return
			}
		} else if strings.HasPrefix(arg, "-") {
			for j := 1; j < len(arg); j++ {
				switch arg[j] {
				case 'u': opts.ungron = true
				case 'v': opts.values = true
				case 'c': opts.colorize = true
				case 'm': opts.monochrome = true
				case 's': opts.stream = true
				case 'k': opts.insecure = true
				case 'j': opts.json = true
				}
			}
		} else {
			args = append(args, arg)
		}
	}

	if opts.version {
		fmt.Println("gron version dev")
		return
	}

	if !opts.monochrome && !opts.colorize {
		fileInfo, _ := os.Stdout.Stat()
		if (fileInfo.Mode() & os.ModeCharDevice) != 0 {
			opts.colorize = true
		}
	}
	if opts.monochrome {
		opts.colorize = false
	}

	var input io.Reader
	if len(args) == 0 || args[0] == "-" {
		input = os.Stdin
	} else {
		arg := args[0]
		if strings.HasPrefix(arg, "http://") || strings.HasPrefix(arg, "https://") {
			resp, err := http.Get(arg)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err)
				os.Exit(4)
			}
			defer resp.Body.Close()
			input = resp.Body
		} else {
			f, err := os.Open(arg)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s\n", err)
				os.Exit(1)
			}
			defer f.Close()
			input = f
		}
	}

	if opts.ungron {
		doUngron(input, opts)
	} else if opts.values {
		doValues(input, opts)
	} else {
		if opts.stream {
			doStreamGron(input, opts)
		} else {
			var val interface{}
			dec := json.NewDecoder(input)
			dec.UseNumber()
			if err := dec.Decode(&val); err != nil {
				fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err)
				os.Exit(3)
			}
			statements := make([]statement, 0)
			walk(val, []pathComponent{{key: "json"}}, &statements)
			if !opts.noSort {
				sort.Slice(statements, func(i, j int) bool {
					return naturalLess(formatPath(statements[i].path, false), formatPath(statements[j].path, false))
				})
			}
			for _, s := range statements {
				if opts.json {
					fmt.Println(formatJSON(s))
				} else {
					fmt.Println(formatStatement(s, opts.colorize))
				}
			}
		}
	}
}

func walk(val interface{}, path []pathComponent, statements *[]statement) {
	switch v := val.(type) {
	case map[string]interface{}:
		*statements = append(*statements, statement{path, v})
		keys := make([]string, 0, len(v))
		for k := range v {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{key: k})
			walk(v[k], newPath, statements)
		}
	case []interface{}:
		*statements = append(*statements, statement{path, v})
		for i, item := range v {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{isIndex: true, index: i})
			walk(item, newPath, statements)
		}
	default:
		*statements = append(*statements, statement{path, v})
	}
}

func formatPath(path []pathComponent, colorize bool) string {
	var sb strings.Builder
	for i, comp := range path {
		if i == 0 {
			if colorize {
				sb.WriteString("\x1b[34;1m" + comp.key + "\x1b[0;22m")
			} else {
				sb.WriteString(comp.key)
			}
		} else if comp.isIndex {
			if colorize {
				sb.WriteString("\x1b[35m[\x1b[0m\x1b[31m" + strconv.Itoa(comp.index) + "\x1b[0m\x1b[35m]\x1b[0m")
			} else {
				sb.WriteString("[" + strconv.Itoa(comp.index) + "]")
			}
		} else {
			if isIdentifier(comp.key) {
				if colorize {
					sb.WriteString(".\x1b[34;1m" + comp.key + "\x1b[0;22m")
				} else {
					sb.WriteString("." + comp.key)
				}
			} else {
				if colorize {
					sb.WriteString("\x1b[35m[\x1b[0m\x1b[33m" + quoteString(comp.key) + "\x1b[0m\x1b[35m]\x1b[0m")
				} else {
					sb.WriteString("[" + quoteString(comp.key) + "]")
				}
			}
		}
	}
	return sb.String()
}

func isIdentifier(s string) bool {
	if s == "" || reservedWords[s] {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !unicode.IsLetter(r) && r != '$' && r != '_' {
				return false
			}
		} else {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '$' && r != '_' {
				return false
			}
		}
	}
	return true
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "export": true, "extends": true, "false": true, "finally": true,
	"for": true, "function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true, "super": true,
	"switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
	"yield": true,
}

func quoteString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

func formatValue(val interface{}, colorize bool) string {
	switch v := val.(type) {
	case map[string]interface{}:
		if colorize { return "\x1b[35m{}\x1b[0m" }
		return "{}"
	case []interface{}:
		if colorize { return "\x1b[35m[]\x1b[0m" }
		return "[]"
	case json.Number:
		if colorize { return "\x1b[31m" + v.String() + "\x1b[0m" }
		return v.String()
	case string:
		if colorize { return "\x1b[33m" + quoteString(v) + "\x1b[0m" }
		return quoteString(v)
	case bool:
		s := strconv.FormatBool(v)
		if colorize { return "\x1b[36m" + s + "\x1b[0m" }
		return s
	case nil:
		if colorize { return "\x1b[36mnull\x1b[0m" }
		return "null"
	default:
		return fmt.Sprintf("%v", v)
	}
}

func formatStatement(s statement, colorize bool) string {
	return formatPath(s.path, colorize) + " = " + formatValue(s.value, colorize) + ";"
}

func formatJSON(s statement) string {
	pathArray := make([]interface{}, 0, len(s.path)-1)
	for i := 1; i < len(s.path); i++ {
		if s.path[i].isIndex { pathArray = append(pathArray, s.path[i].index) } else { pathArray = append(pathArray, s.path[i].key) }
	}
	val := s.value
	if _, ok := val.(map[string]interface{}); ok { val = map[string]interface{}{} } else if _, ok := val.([]interface{}); ok { val = []interface{}{} }
	res, _ := json.Marshal([]interface{}{pathArray, val})
	return string(res)
}

func naturalLess(s1, s2 string) bool {
	i, j := 0, 0
	for i < len(s1) && j < len(s2) {
		if unicode.IsDigit(rune(s1[i])) && unicode.IsDigit(rune(s2[j])) {
			k1 := i
			for k1 < len(s1) && unicode.IsDigit(rune(s1[k1])) { k1++ }
			k2 := j
			for k2 < len(s2) && unicode.IsDigit(rune(s2[k2])) { k2++ }
			num1, _ := strconv.Atoi(s1[i:k1])
			num2, _ := strconv.Atoi(s2[j:k2])
			if num1 != num2 { return num1 < num2 }
			if (k1 - i) != (k2 - j) { return (k1 - i) < (k2 - j) }
			i, j = k1, k2
		} else {
			if s1[i] != s2[j] { return s1[i] < s2[j] }
			i++; j++
		}
	}
	return len(s1) < len(s2)
}

func printHelp() {
	fmt.Print(`Transform JSON (from a file, URL, or stdin) into discrete assignments to make it greppable

Usage:
  gron [OPTIONS] [FILE|URL|-]

Options:
  -u, --ungron     Reverse the operation (turn assignments back into JSON)
  -v, --values     Print just the values of provided assignments
  -c, --colorize   Colorize output (default on tty)
  -m, --monochrome Monochrome (don't colorize output)
  -s, --stream     Treat each line of input as a separate JSON object
  -k, --insecure   Disable certificate validation
  -x, --proxy      Set proxy configuration
      --noproxy    Comma-separated list of hosts for which not to use a proxy, if one is specified.
  -j, --json       Represent gron data as JSON stream
      --no-sort    Don't sort output (faster)
      --version    Print version information

Exit Codes:
  0	OK
  1	Failed to open file
  2	Failed to read input
  3	Failed to form statements
  4	Failed to fetch URL
  5	Failed to parse statements
  6	Failed to encode JSON

Examples:
  gron /tmp/apiresponse.json
  gron http://jsonplaceholder.typicode.com/users/1 
  curl -s http://jsonplaceholder.typicode.com/users/1 | gron
  gron http://jsonplaceholder.typicode.com/users/1 | grep company | gron --ungron
`)
}

func doStreamGron(input io.Reader, opts flagOptions) {
	scanner := bufio.NewScanner(input)
	i := 0
	var allStatements []statement
	allStatements = append(allStatements, statement{path: []pathComponent{{key: "json"}}, value: []interface{}{}})
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 { continue }
		var val interface{}
		dec := json.NewDecoder(strings.NewReader(string(line)))
		dec.UseNumber()
		if err := dec.Decode(&val); err != nil { continue }
		walk(val, []pathComponent{{key: "json"}, {isIndex: true, index: i}}, &allStatements)
		i++
	}
	if !opts.noSort {
		sort.Slice(allStatements, func(i, j int) bool { return naturalLess(formatPath(allStatements[i].path, false), formatPath(allStatements[j].path, false)) })
	}
	for _, s := range allStatements {
		if opts.json { fmt.Println(formatJSON(s)) } else { fmt.Println(formatStatement(s, opts.colorize)) }
	}
}

func doValues(input io.Reader, opts flagOptions) {
	scanner := bufio.NewScanner(input)
	for scanner.Scan() {
		line := scanner.Text()
		idx := strings.Index(line, " = ")
		if idx == -1 { continue }
		valStr := line[idx+3:]
		if strings.HasSuffix(valStr, ";") { valStr = valStr[:len(valStr)-1] }
		var val interface{}
		dec := json.NewDecoder(strings.NewReader(valStr))
		dec.UseNumber()
		if err := dec.Decode(&val); err != nil { continue }
		switch v := val.(type) {
		case string: fmt.Println(v)
		case json.Number: fmt.Println(v.String())
		case bool: fmt.Println(v)
		case nil: fmt.Println("null")
		}
	}
}

func doUngron(input io.Reader, opts flagOptions) {
	scanner := bufio.NewScanner(input)
	var root interface{}
	hasStatements := false
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" { continue }
		var pathComps []pathComponent
		var val interface{}
		if opts.json {
			var data []interface{}
			if err := json.Unmarshal([]byte(line), &data); err != nil { continue }
			if len(data) != 2 { continue }
			pathArray, _ := data[0].([]interface{})
			pathComps = append(pathComps, pathComponent{key: "json"})
			for _, p := range pathArray {
				switch v := p.(type) {
				case string: pathComps = append(pathComps, pathComponent{key: v})
				case json.Number: idx, _ := strconv.Atoi(v.String()); pathComps = append(pathComps, pathComponent{isIndex: true, index: idx})
				case float64: pathComps = append(pathComps, pathComponent{isIndex: true, index: int(v)})
				}
			}
			val = data[1]
		} else {
			comps, i, err := decodePath(line)
			if err != nil { fmt.Fprintf(os.Stderr, "ungron failed for `%s`: %s\n", line, err); os.Exit(5) }
			pathComps = comps
			for i < len(line) && (line[i] == ' ' || line[i] == '=') { i++ }
			valStr := line[i:]
			if strings.HasSuffix(valStr, ";") { valStr = valStr[:len(valStr)-1] }
			if valStr == "" { fmt.Fprintf(os.Stderr, "ungron failed for `%s`: statement has no value\n", line); os.Exit(5) }
			dec := json.NewDecoder(strings.NewReader(valStr))
			dec.UseNumber()
			if err := dec.Decode(&val); err != nil { fmt.Fprintf(os.Stderr, "ungron failed for `%s`: invalid value `%s`\n", line, valStr); os.Exit(5) }
		}
		if len(pathComps) > 0 && pathComps[0].key == "json" { pathComps = pathComps[1:] }
		if err := setPath(&root, pathComps, val); err != nil { fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", err); os.Exit(5) }
		hasStatements = true
	}
	if !hasStatements { fmt.Fprintf(os.Stderr, "no statements were parsed\n"); os.Exit(5) }
	out, _ := json.MarshalIndent(root, "", "  ")
	fmt.Println(string(out))
}

func decodePath(s string) ([]pathComponent, int, error) {
	var comps []pathComponent
	i := 0
	start := i
	for i < len(s) && (unicode.IsLetter(rune(s[i])) || s[i] == '$' || s[i] == '_' || (i > start && unicode.IsDigit(rune(s[i])))) { i++ }
	if i > start { comps = append(comps, pathComponent{key: s[start:i]}) }
	for i < len(s) {
		if s[i] == '.' {
			i++; start = i
			for i < len(s) && (unicode.IsLetter(rune(s[i])) || s[i] == '$' || s[i] == '_' || (i > start && unicode.IsDigit(rune(s[i])))) { i++ }
			if i > start { comps = append(comps, pathComponent{key: s[start:i]}) } else { return nil, i, fmt.Errorf("expected identifier after .") }
		} else if s[i] == '[' {
			i++
			if i < len(s) && s[i] == '"' {
				j := i; i++
				for i < len(s) && s[i] != '"' { if s[i] == '\\' { i++ }; i++ }
				if i < len(s) && s[i] == '"' {
					i++; var key string
					err := json.Unmarshal([]byte(s[j:i]), &key)
					if err != nil { return nil, i, err }
					comps = append(comps, pathComponent{key: key})
					if i < len(s) && s[i] == ']' { i++ } else { return nil, i, fmt.Errorf("expected ] after bracketed string") }
				} else { return nil, i, fmt.Errorf("unclosed string in brackets") }
			} else {
				start = i
				for i < len(s) && unicode.IsDigit(rune(s[i])) { i++ }
				if i > start && i < len(s) && s[i] == ']' {
					idx, _ := strconv.Atoi(s[start:i])
					comps = append(comps, pathComponent{isIndex: true, index: idx})
					i++
				} else { return nil, i, fmt.Errorf("expected index in brackets") }
			}
		} else { break }
	}
	if len(comps) == 0 && len(s) > 0 && s[0] != ' ' && s[0] != '=' { return nil, 0, fmt.Errorf("invalid statement") }
	return comps, i, nil
}

func setPath(root *interface{}, path []pathComponent, value interface{}) error {
	if len(path) == 0 { *root = value; return nil }
	comp := path[0]
	if comp.isIndex {
		arr, ok := (*root).([]interface{})
		if !ok {
			if *root != nil { return fmt.Errorf("cannot merge array with non-array") }
			arr = []interface{}{}
		}
		for len(arr) <= comp.index { arr = append(arr, nil) }
		if err := setPath(&arr[comp.index], path[1:], value); err != nil { return err }
		*root = arr
	} else {
		m, ok := (*root).(map[string]interface{})
		if !ok {
			if _, ok := (*root).([]interface{}); ok { return fmt.Errorf("cannot merge object with non-object") }
			m = make(map[string]interface{})
		}
		if err := setPath(&m[comp.key], path[1:], value); err != nil { return err }
		*root = m
	}
	return nil
}
