func walk(val interface{}, path []pathComponent, statements *[]statement) {
	switch v := val.(type) {
	case map[string]interface{}:
		*statements = append(*statements, statement{path, v})
		keys := make([]string, 0, len(v))
		for k := range v { keys = append(keys, k) }
		sort.Strings(keys)
		for _, k := range keys {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{key: k})
			walk(v[k], newPath, statements)
		}
	case []interface{}:
		*statements = append(*statements, statement{path, v})
		for i, item := range v {
			newPath := append([]pathComponent{}, path...)
			newPath = append(newPath, pathComponent{isIndex: true, index: i})
			walk(item, newPath, statements)
		}
	default:
		*statements = append(*statements, statement{path, v})
	}
}

func formatPath(path []pathComponent, colorize bool) string {
	var sb strings.Builder
	for i, comp := range path {
		if i == 0 {
			if colorize { sb.WriteString("\x1b[34;1m" + comp.key + "\x1b[0;22m") } else { sb.WriteString(comp.key) }
		} else if comp.isIndex {
			if colorize { sb.WriteString("\x1b[35m[\x1b[0m\x1b[31m" + strconv.Itoa(comp.index) + "\x1b[0m\x1b[35m]\x1b[0m") } else { sb.WriteString("[" + strconv.Itoa(comp.index) + "]") }
		} else {
			if isIdentifier(comp.key) {
				if colorize { sb.WriteString(".\x1b[34;1m" + comp.key + "\x1b[0;22m") } else { sb.WriteString("." + comp.key) }
			} else {
				if colorize { sb.WriteString("\x1b[35m[\x1b[0m\x1b[33m" + quoteString(comp.key) + "\x1b[0m\x1b[35m]\x1b[0m") } else { sb.WriteString("[" + quoteString(comp.key) + "]") }
			}
		}
	}
	return sb.String()
}

func isIdentifier(s string) bool {
	if s == "" || reservedWords[s] { return false }
	for i, r := range s {
		if i == 0 {
			if !unicode.IsLetter(r) && r != '$' && r != '_' { return false }
		} else {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '$' && r != '_' { return false }
		}
	}
	return true
}

var reservedWords = map[string]bool{
